OEVENTLUA[1901] = function ()
	Cls()
	say("到这时候还不拿出来？姓吴的，你到底识不识时务？", 1035, 0, "安寨主")
	say("素闻金刀寨安寨主劫富济贫，江湖上提起来，都是翘起大拇指，说一声：‘侠盗！’怎么今日却向卖烧饼的穷老汉打起主意来啦？", 1034, 1)
	say("吴道通，你是决计不交出来的啦？", 1035, 0, "安寨主")

	if yesno("要上去阻止争执吗？") then
		say("喂，你们这是在争抢什么东西？", 0, 1)
		say("臭小子，赶快滚开！", 1035, 0, "安寨主")
		say("小子，赶快滚开，这儿没你的事。", 1034, 1)
		say("大家以和为贵，不要为点小事伤了和气。", 0, 0)
		say("聒噪，既然你不走，那就别走了！", 1035, 1, "安寨主")

		if WarMain(334, 0, 1, 1) == false then
			instruct_15(0)
			instruct_0()

			return
		end

		dark()
		null(-2, 13)
		null(-2, 14)
		null(-2, 15)
		null(-2, 16)
		light()
		instruct_40(1)
		say("东西拿出来，让我看看。", 0, 1)
		say("少侠武功高强，我是佩服的。不过东西不在我身上，无论如何也是拿不出来的。", 1034, 0)
		say("真是，非要我动手么。", 0, 1)
		DrawStrBoxWaitKey("那吴道通见你逼了上来，将满桌的烧饼一股脑向你掷了过来", C_ORANGE, CC.DefaultFont, 2)
		say("哼。", 0, 1)
		say("啊~", 1034, 0)
		dark()
		null(-2, 12)
		light()
		addthing(174, 50)
		say("他们究竟在争抢什么东西？怎么什么也没有找到？", 0, 1)
	else
		say("先看看。", 0, 1)
		dark()
		null(-2, 12)
		light()
		say("吴道通，今日看你能跑到哪里去？小的们，给我追。", 1035, 0, "安寨主")
		dark()
		null(-2, 13)
		null(-2, 14)
		null(-2, 15)
		null(-2, 16)
		light()
		DrawStrBoxWaitKey("只见地上散落了满地的烧饼", C_ORANGE, CC.DefaultFont, 2)
		say("都走了，究竟在争抢什么东西？", 0, 1)
	end

