	say("曲洋曲大哥，是我生平唯一知己，最要好的朋友。我和曲大哥相交，只是研讨音律。偶然涉及门户宗派的异见，他总是深自叹息，认为双方如此争斗，殊属无谓。", 1026, 1, "刘正风")
	say("曲大哥虽是魔教中人，但自他琴音之中，我深知他性行高洁，大有光风霁月的襟怀。刘正风不但对他钦佩，抑且仰慕。刘某虽是一介鄙夫，却决计不肯加害这位君子。", 1026, 1, "刘正风")
	say("岳师兄，你是位明辨是非的君子，这里许多位武林高人都逼我出卖朋友，你却怎么说？", 1026, 1, "刘正风")
