OEVENTLUA[2091] = function ()
	Cls()

	if has_thing(67) == false then
		say("师傅，咱们华山派的紫霞秘籍呢？徒儿想观摩一下。", 0, 1)
		say("你这个逆徒，你到底想干什么？", 19, 0)
		say("师傅，识时务者为俊杰，你就好好在华山呆着，我相信你不会置华山于不顾的。", 0, 1)
		say("哼！", 19, 0)
		addthing(67, 1)
	elseif has_thing(93) then
		say("师傅，你过得怎么样了？", 0, 1)
		say("哼。", 19, 0)
		say("师傅，你也别生气了，以后华山派发扬光大了，你也是功臣之一。", 0, 1)
	else
		say("师傅，你过得怎么样了？", 0, 1)
		say("你这个逆徒，我要看看你是怎么把华山派毁掉的。", 19, 0)
		say("师傅，你不用担心，我会将华山派发扬光大的。", 0, 1)
		say("不过师傅，你也知道我年轻识浅，现在初任五岳掌门，只怕镇压不住阵脚，还需要师父帮忙啊。", 0, 1)
		say("逆徒，你还想我帮你？", 19, 0)
		say("无论如何，现在华山派统一了五岳剑派，师父要是想华山派此次失败，从此一蹶不振，甚至派毁人亡，那也由得师父。", 0, 1)
		say("你到底要做什么？", 19, 0)
		say("我要趁此良机，攻打魔教。", 0, 1)
		say("你疯了？", 19, 0)
		say("还请师父相助。", 0, 1)
		say("哼，你想得倒好。", 19, 0)
	end
end
