OEVENTLUA[2094] = function ()
	Cls()
	dark()
	light()
	say("东方不败，今日终于……终于教你落在我手里。", 26, 0)
	say("卑鄙，如不是你们用莲弟威胁，即使你们一起上，也不是我的对手。", 27, 1)
	meet_self(27)
	say("不错，你武功比我高，我很是佩服。", 26, 0)
	say("可惜，你练了那“葵花宝典”，照着宝典上的秘方，自宫练气，连性子也变了。不然又如何能受我威胁，导致今日一败涂地。", 26, 0)
	say("我知你当年传我《葵花宝典》没安好心，不过我却是感激你的，整日在江湖上争权夺利有什么意思？我终于知道自己想要的是什么，即使几天死了也不后悔，我只求你救救莲弟。", 27, 1)
	say("哈哈哈，你要我救他，我偏要他死，你将我关在西湖地下时没想到会有今日吧，哈哈哈哈哈。", 26, 0)
	Cls()
	say("哈哈哈。", 0, 1)
	say("哈哈哈哈哈。", 0, 1)
	say("什么人？", 26, 0)
	My_Enter_SubScene(26, 18, 28, 1)
	say(JY.Person[0].称呼 .. "，你怎么也来了？", 35, 1)
	say("哎，令狐兄，你怎么也来凑这热闹来了？", 0, 0)
	say("不过你这次却是帮错人啦！", 0, 0)
	say("我...", 35, 1)
	say("我知道你为人侠义，至情至性，不过", 0, 1)
	say("你知道这位任先生是魔教老魔头，你可知道他杀过多少人？在他的命令下又多少人家破人亡？", 0, 1)
	say(JY.Person[0].称呼 .. "我...", 35, 0)
